VALUES
  ('ch2_KAL-001', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा राजस्थान के किस जिले में स्थित है?', 'हनुमानगढ़ जिले में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-001 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '86683b7772ea4d84d44b94f028baa066af3033c564ed55803afdbc230e625587', NULL),
  ('ch2_KAL-002', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा किस नदी के बाएँ किनारे पर स्थित है?', 'वर्तमान में अधिकांशतः सूखी घग्घर नदी के बाएँ किनारे पर; गज़ेटियर इसे प्राचीन सरस्वती से जोड़ता है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-002 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9a2187e29337c4d5da9e057a370ea37c5090eb6940710a3fef2a172a1aa925e2', NULL),
  ('ch2_KAL-003', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा हनुमानगढ़ जिले के किस खंड में स्थित है?', 'पीलीबंगा खंड में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-003 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '88a7959b7b7b66a618f6099be2bc1284e2eb945db6f3f1ce7b7471c8192c07e7', NULL),
  ('ch2_KAL-004', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर में कालीबंगा के निर्देशांक क्या दिए गए हैं?', 'लगभग 29° 29′ उत्तरी अक्षांश और 74° 08′ पूर्वी देशांतर।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-004 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '523505608ea3203729646b9e0540fa92e96dcd20c58d2b138d664a9d018e34c7', NULL),
  ('ch2_KAL-005', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा किस सभ्यता का प्रमुख पुरातात्त्विक स्थल है?', 'हड़प्पा / सिंधु सभ्यता का।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-005 — S4 — printed pp. 34–37; S1 — “Kalibangan” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b8d49442ffaf2d8d6dc220456acb541e16bc110fe6bb42719e7251b3bff108b8', NULL),
  ('ch2_KAL-006', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के पुरातात्त्विक स्थल पर किन दो सांस्कृतिक चरणों के प्रमाण मिले हैं?', 'प्रारम्भिक हड़प्पा और परिपक्व हड़प्पा चरणों के।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-006 — S4 — printed pp. 36–37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3bfa58cbb5dc3fa7b446fb407c8b9119832a419c8cd3d53ce511a07761bc850b', NULL),
  ('ch2_KAL-007', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा प्रथम (KLB-I) किस सांस्कृतिक चरण से संबंधित है?', 'प्रारम्भिक हड़प्पा / पूर्ववर्ती हड़प्पा चरण से।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-007 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0ad9c57f0913116cf3cee2c0266835fed4b6eed4e3961b7e0de7b74875bdb8be', NULL),
  ('ch2_KAL-008', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा द्वितीय (KLB-II) किस सांस्कृतिक चरण से संबंधित है?', 'परिपक्व हड़प्पा चरण से।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-008 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a56a82f1b288bbac72be9b57a799488555bb14dabacfd2980414b0a9a5388225', NULL),
  ('ch2_KAL-009', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर के अनुसार प्रारम्भिक हड़प्पा संस्कृति का अनुमानित काल कौन-सा है?', 'लगभग 3000–2700 ईसा पूर्व।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-009 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a181435c0d7c13ffc964c200c714e9419f83efbd0568c884c20338ef44ff8461', NULL),
  ('ch2_KAL-010', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर के अनुसार परिपक्व हड़प्पा संस्कृति का अनुमानित काल कौन-सा है?', 'लगभग 2600–1900 ईसा पूर्व।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-010 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4d8e30c206d3a162e2eda934cf8cedfc6076290fffaa676240fe42d86d41e5b2', NULL),
  ('ch2_KAL-011', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की खोज और पहचान के इतिहास में 1952 में किसका नाम आता है?', 'श्री अमलानंद घोष ने 1952 के अपने अन्वेषण के दौरान इस स्थल को पहली बार प्रमुखता से सामने रखा।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-011 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'cd262425fd53e4eb0faec7b389a25c1fa71dde44a4e3137ebcd56dbc3ed35b41', NULL),
  ('ch2_KAL-012', 'catalog.rajasthan_history_ancient_history_kalibangan', 'एल. पी. टेसिटोरी ने कालीबंगा क्षेत्र का सर्वेक्षण किस अवधि में किया?', '1916–1919 के अपने राजपूताना सर्वेक्षण के दौरान; उन्होंने 1917 और 1918 में स्थल का दौरा किया।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-012 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a42ac0c768d8d29920e71e316c852758ac516f3050d22f79a7539eb7cc994064', NULL),
  ('ch2_KAL-013', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा क्षेत्र का सर्वेक्षण करने वाले ऑरेल स्टाइन ने यहाँ कब सर्वेक्षण किया?', 'दिसंबर 1941 में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-013 — S4 — printed pp. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8b297e23b314a9dc197a0911c13f25518c37cd77a863f61549e44a47b0ad4793', NULL),
  ('ch2_KAL-014', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर कालीबंगा का सबसे पुराना दर्ज लिखित उल्लेख किससे जोड़ता है?', 'जेम्स टॉड से; गज़ेटियर इसे सबसे पुराना संभावित लिखित उल्लेख कहता है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-014 — S4 — printed p. 36; wording is qualified — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0621b37a4c00797df02b217e7a5cb153104e2b30ab37dfb0bf7e40b0cd8bfa57', NULL),
  ('ch2_KAL-015', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा का व्यवस्थित उत्खनन किस संस्था के अधीन हुआ?', 'भारतीय पुरातत्व सर्वेक्षण (भा.पु.स.) के अधीन।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-015 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '7a80df9673ae2a7b92738781f0dc1fa64aac5a5c1bb30d40fd39eccae11a6165', NULL),
  ('ch2_KAL-016', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा का प्रमुख उत्खनन किस अवधि में हुआ?', '1961 से 1969 के बीच।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-016 — S4 — printed pp. 34–36; S1 — “Kalibangan” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2592c13e1ddffff91da8ad5b7a499dce61f6d1fe7a7472d9c71f80307a236aae', NULL),
  ('ch2_KAL-017', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा का उत्खनन कितने सत्रों में किया गया?', 'नौ उत्खनन सत्रों में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-017 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '54f1b306f2f9e32740ebba70f850d42bbe0fd814fd93e57ef2ce430713aa8d43', NULL),
  ('ch2_KAL-018', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के उत्खनन से जुड़े प्रमुख पुरातत्वविद् कौन थे?', 'प्रो. बी. बी. लाल, बी. के. थापर और जे. पी. जोशी।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-018 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9242210cf5922a3c29671628785450f0336f74e2653a24432334c876c2b862b0', NULL),
  ('ch2_KAL-019', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा स्थल पर कितने मुख्य क्रमांकित टीलों (KLB-1, KLB-2, KLB-3) का वर्णन है?', 'तीन। इनके अतिरिक्त समाधि-टीले KLB-8 का भी उल्लेख है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-019 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3ce0aa8cc6c7789739346f3585df4c3c1ddd73e4330a80d1720b2a817f0ecb3c', NULL),
  ('ch2_KAL-020', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-1 टीला किस दिशा में और किस संस्कृति से संबंधित था?', 'पश्चिम में स्थित छोटा टीला; प्रारम्भिक हड़प्पा संस्कृति से संबंधित।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-020 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5e85a8ac4110cf52446882d4da11d53fab424e1231394f0e35e776fb49ec123a', NULL),
  ('ch2_KAL-021', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-2 टीला कहाँ स्थित था और किस चरण से संबंधित था?', 'बीच में स्थित सबसे बड़ा टीला; परिपक्व हड़प्पा चरण से संबंधित।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-021 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e3b9226922a8433099b8528ebc858025130cf9d6b56207b893dd3c0707892c4e', NULL),
  ('ch2_KAL-022', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-3 टीला कहाँ स्थित था और किस चरण से संबंधित था?', 'पूर्व में स्थित सबसे छोटा टीला; परिपक्व हड़प्पा चरण से संबंधित।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-022 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0953c271f1521fe83b5f7ec2d4d32d960790492ab191845d1627b1b572a81b22', NULL),
  ('ch2_KAL-023', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा का समाधि-टीला किस संकेतांक से पहचाना गया है?', 'KLB-8।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-023 — S4 — printed p. 36; S6 — Ch. 22, Figs. 22.2–22.3, printed pp. 1288–1290; S7 — Burial Site (KLB-8) — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'f1ea33e2359478a973ec961d72e94b8c4d51bb67ff3c41f1d0375ebb29a1cbb5', NULL),
  ('ch2_KAL-024', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-8 समाधि-टीला मुख्य स्थल के किस भाग में स्थित बताया गया है?', 'दुर्ग क्षेत्र के दक्षिण-पश्चिम में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-024 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'cf8f5594ec89b084e6c7ff05761bd7b213d31dae148efc8c4ffaf37d05bcc500', NULL),
  ('ch2_KAL-025', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर में कालीबंगा के समाधि-क्षेत्र से किस प्रकार के शवाधान बताए गए हैं?', 'आयताकार या अंडाकार कब्र-गड्ढे, गोलाकार गड्ढे में मृद्भांड सहित शवाधान, तथा मृद्भांड और अंत्येष्टि सामग्री वाले आयताकार या अंडाकार गड्ढे।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-025 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1e9efa5016cf160261bbc856bf8ba0b11ee252524aa61519919f11a1babe7544', NULL),
  ('ch2_KAL-026', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रारम्भिक हड़प्पा काल की कालीबंगा बस्ती का आकार कैसा था?', 'दुर्गीकृत समांतर चतुर्भुज जैसा।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-026 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '62147ecf7c65367a84c28df6ef461eaae27df142c0441a6290e5196cb5880a61', NULL),
  ('ch2_KAL-027', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रारम्भिक हड़प्पा बस्ती का अनुमानित आकार कितना था?', 'उत्तर-दक्षिण लगभग 250 मीटर और पूर्व-पश्चिम लगभग 180 मीटर।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-027 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'df693f615429effee6a2162a6193e07e7f1a07be9e59d776f71ada5fe79da1b5', NULL),
  ('ch2_KAL-028', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रारम्भिक हड़प्पा बस्ती की किलेबंदी किस सामग्री से बनी थी?', 'कच्ची ईंटों से।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-028 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5b22912b339e26c8fdc6324ddb360c6daf2c37b4c8d98e385a346eb46a296efe', NULL),
  ('ch2_KAL-029', 'catalog.rajasthan_history_ancient_history_kalibangan', 'गज़ेटियर प्रारम्भिक हड़प्पा किलेबंदी में प्रयुक्त कच्ची ईंटों का आकार क्या बताता है?', 'लगभग 30 × 20 × 10 सेंटीमीटर।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-029 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0cad9ca69392bf20653662de8fdbb370d3b1b0006150fc07eee919c439561e0b', NULL),
  ('ch2_KAL-030', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा में जुते हुए खेत का प्रमाण बस्ती के किस दिशा-भाग में मिला?', 'बस्ती के दक्षिण-पूर्व में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-030 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2d6f36533ff4508b6e77f98976ae8e5fb7262cb251880da7bbce4fd2e3453994', NULL),
  ('ch2_KAL-031', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के जुते खेत में हल-रेखाओं का कौन-सा विन्यास मिला?', 'हल-रेखाओं का प्रतिच्छेदी विन्यास; दो समूह एक-दूसरे को समकोण पर काटते थे।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-031 — S4 — printed p. 37; S2 — §2.1, printed p. 3 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2a09e54abd6591977bad4e4533f1003cb978501a4f38d95f73c287b10a4c21dc', NULL),
  ('ch2_KAL-032', 'catalog.rajasthan_history_ancient_history_kalibangan', 'खेत में दो दिशाओं की हल-रेखाओं से किस कृषि-पद्धति का संकेत मिलता है?', 'एक ही खेत में दो अलग-अलग फसलें साथ उगाने का संकेत।', 'hi', 'https://ncert.nic.in/textbook/pdf/lehs101.pdf', 'KAL-032 — S2 — Ch. 1, §2.1 “Agricultural technologies”, printed p. 3 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'eb9643b9b636bbf0cb86c000ee9b0422396c73f54d727269b08c5cb53df01261', NULL),
  ('ch2_KAL-033', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के जुते खेत को “विश्व का सबसे पुराना” कहने में कौन-सी सावधानी जरूरी है?', 'जिला गज़ेटियर “संभवतः” कहता है; इसलिए इसे निर्विवाद तथ्य नहीं, बल्कि गज़ेटियर का सशर्त कथन ही बताना चाहिए।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-033 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '976567e8032a36c882380cbf016c1205cb6a7cb3b94aaebb340b505980f742f1', NULL),
  ('ch2_KAL-034', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रारम्भिक हड़प्पा चरण के मृद्भांड किस प्रकार बनाए जाते थे?', 'गज़ेटियर के अनुसार मृद्भांड चाक पर बनाए जाते थे और लगभग 400–600°से पर पकाए जाते थे।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-034 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '157b7788953908079d9fdbf5cbca6c3de2ccaff1dbbd8f7536bbf7df7c927cdc', NULL),
  ('ch2_KAL-035', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रारम्भिक हड़प्पा मृद्भांडों को तकनीक के आधार पर कितनी श्रेणियों में बाँटा गया?', 'छह श्रेणियों में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-035 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4bbe94640d9d6b947db6446f276ee22aa356746d40fdd6d414912238ab6d17f8', NULL),
  ('ch2_KAL-036', 'catalog.rajasthan_history_ancient_history_kalibangan', 'परिपक्व हड़प्पा चरण के मृद्भांड किस प्रकार के चाक पर बनाए जाते थे?', 'तेज़ गति से घूमने वाले चाक पर।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-036 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '065d9cb33dce1b6a549fbec5c8bb2579c29238cfc4071f53ddf871148dfd9403', NULL),
  ('ch2_KAL-037', 'catalog.rajasthan_history_ancient_history_kalibangan', 'गज़ेटियर के अनुसार परिपक्व हड़प्पा मृद्भांडों को लगभग किस तापमान पर पकाया गया?', 'लगभग 930°से पर।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-037 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2f9f4a42fd994dfb21246cb8f8bed6b86b837b55011a4f4abbd1dcfeba126a52', NULL),
  ('ch2_KAL-038', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रारम्भिक हड़प्पा बस्ती के छोड़े जाने का संभावित कारण क्या बताया गया है?', 'लगभग 2700 ईसा पूर्व के आसपास भूकंप की संभावना बताई गई है, लेकिन गज़ेटियर स्पष्ट करता है कि यह निर्णायक रूप से सिद्ध नहीं है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-038 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '917b761fc0b1a46b6023e8acf1c5540140f9b9c1832e7bcbd52f3b991c42f08b', NULL),
  ('ch2_KAL-039', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रारम्भिक हड़प्पा बसावट के बाद कालीबंगा में किस चरण के लोग फिर बसे?', 'परिपक्व हड़प्पा संस्कृति के लोग।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-039 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a0f7ad277d06d81b3e7434698183c04a237fbcc66f04cc1366bf0ff42ef10155', NULL),
  ('ch2_KAL-040', 'catalog.rajasthan_history_ancient_history_kalibangan', 'परिपक्व हड़प्पा काल में कालीबंगा नगर के दो प्रमुख भाग कौन-से थे?', 'पश्चिम में दुर्ग क्षेत्र और पूर्व में निचला नगर।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-040 — S4 — printed p. 37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1a8671f604b4fd1728f2312f7b2faaea229296414035b2783be04c1fbd7b5e83', NULL),
