  ('ch2_BRT-008', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ के दो अशोक-कालीन अभिलेखों के नाम संबंधित अध्ययन में कौन-से दिए गए हैं?', 'कलकत्ता-बैराठ शिलालेख और लघु शिलालेख प्रथम।', 'hi', 'https://pmml.nic.in/downloadSeries/342', 'BRT-008 — S27 — PMML, “Understanding the Ashokan Inscriptions and the Archaeological Landscape of Bairat” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '122d8f6728c3087ac492488f1e22b19d7866a354d83f114b2f5fc4c1c9790d04', NULL),
  ('ch2_BRT-009', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ के उत्खनित स्थल को भारतीय पुरातत्व सर्वेक्षण की सूची में किस अधिनियम से जोड़ा गया है?', '1951 के अधिनियम संख्या 71, दिनांक 28 नवम्बर 1951 से।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-009 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c5b9f3ef327d5cfb6c71567f7d74c419433030f1169153d45eddfa316a1b896c', NULL),
  ('ch2_BRT-010', 'catalog.rajasthan_history_ancient_history_bairat', 'कलकत्ता-बैराठ शिलालेख में अशोक ने किनके प्रति अपनी श्रद्धा व्यक्त की और कितने धम्म-विषयक पाठों को बार-बार सुनने की अनुशंसा की?', 'बुद्ध, धम्म और संघ के प्रति श्रद्धा; सात धम्म-विषयक पाठों को भिक्षुओं और भिक्षुणियों द्वारा बार-बार सुनने-मनन करने की इच्छा, तथा उपासकों और उपासिकाओं के लिए भी वैसा ही निर्देश।', 'hi', 'https://pmml.nic.in/downloadSeries/342', 'BRT-010 — S27 — Meenakshi Vashisth, “Text and Context: Understanding the Ashokan Inscriptions and the Archaeological Landscape of Bairat”, “Translation” खंड, पंक्तियाँ 126–135; सात पाठों की पहचान पर विद्वानों में जटिलता का उल्लेख पंक्तियाँ 271–273 — स्वतंत्र अभिलेखीय समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '7275d651d1af52cb7374395c6d0de5afd46fa8dc6fc34447cd215603e78317fc', NULL),
  ('ch2_BRT-011', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ की बिजक-की-पहाड़ी पर 1935–36 के उत्खनन में रायबहादुर दयाराम साहनी को बौद्ध अवशेष कहाँ-कहाँ मिले?', 'दो धरातलों पर—ऊँचे धरातल पर ईंटों का मठ और निचले धरातल पर ईंटों का मंदिर/पूजास्थल; निचले ढाँचे को वृत्ताकार पवित्र स्थापत्य के रूप में समझा गया।', 'hi', 'https://pmml.nic.in/downloadSeries/342', 'BRT-011 — S27 — Meenakshi Vashisth, “Text and Context…”, “Archaeological significance of the Bairat Region”, पंक्तियाँ 207–210; निचले ढाँचे की व्याख्या उद्धृत उत्खनन-व्याख्या है — स्वतंत्र योजना/रिपोर्ट जाँच लंबित।', 'NEEDS_REVIEW', 0.80, 'ecce1e2aaaf60e3733c156bdf65f6ebcd400d3cfbb71774f9b915b3d344ae06a', NULL),
